mapper.select:
select PUBLIC_KEY_VERSION_STATUS
from METRO_AGM_KEY_VERSION
where PROVIDER_ID = #{providerId,jdbcType=VARCHAR}
  and KEY_BATH_NUMBER = #{batchNumber,jdbcType=NUMERIC}

mapper.update:
update METRO_AGM_KEY_VERSION
set PUBLIC_KEY_VERSION_STATUS = #{toStatus,jdbcType=VARCHAR},
    MANAGER_ID = #{operator,jdbcType=VARCHAR},
    UPDATE_DATE = SYSDATE
where PROVIDER_ID = #{providerId,jdbcType=VARCHAR}
  and KEY_BATH_NUMBER = #{batchNumber,jdbcType=NUMERIC}
  and PUBLIC_KEY_VERSION_STATUS = #{fromStatus,jdbcType=VARCHAR}
